    for t,m in rank: print(f"{t}: avg mood {statistics.mean(m):.1f} (n={len(m)})")
    print("Coach: do more of",rank[0][0],"; watch out for",rank[-1][0])
if __name__=="__main__":
    a=sys.argv[1:]
    add(a[1],a[2]) if a and a[0]=="add" else report()

def trend(n=7):
    m=[e["mood"] for e in load()][-n:]
    if len(m)<2: return "Not enough data"
    d=m[-1]-m[0]; return "Mood rising" if d>0 else "Mood falling" if d<0 else "Mood flat"

